import re
from asyncio import CancelledError, get_running_loop
from collections import Counter
from contextvars import ContextVar
from dataclasses import dataclass
from string.templatelib import Template
from typing import Any, Callable, Generator, Literal, Never  # noqa: UP035

WINDOW = 200000
OPERATOR = "operator"
TIMEOUT = 120.0
LARGEST = 524288
ROOT = "chain1"
site = ContextVar("site", default=OPERATOR)
raised = None
actor = ""
accepts = None
type Show = tuple | Callable[[list[str]], list[int]]
type Filter = Callable[[list[tuple]], list[tuple]]


def ask(kind, on, *words):
  if isinstance(got := peek(a := act(kind, on, None, *words), Refused(a + " not done")), Refused):
    raise got
  return got


def span(lo: int, hi: int) -> Show:
  return "span", lo, hi


def grep(pattern: str) -> Show:
  return "grep", pattern


def differs(old: list[str]) -> Show:
  return "differs", old


def picked(show: Show, lines: list[str]) -> list[int]:
  match show:
    case "span", lo, hi:
      return list(range(1, len(lines) + 1)[lo - (lo > 0) : hi if hi >= 0 else hi + 1 or None])
    case "grep", str() as pattern:
      return [i for i, line in enumerate(lines, 1) if re.search(pattern, line)]
    case "differs", list() as old:
      return [i for i, line in enumerate(lines, 1) if old[i - 1 : i] != [line]]
  return show(lines)  # ty: ignore[call-non-callable]


HEAD, TAIL, HIDDEN = span(1, 2000), span(-250, -1), span(0, 0)


def take(*ids: str, inside=True) -> Filter:
  return lambda facts: [a for a in facts if any(under(a[1], one) for one in ids) == inside]


def read(path: str, show: Show = HEAD, on="") -> Text:
  got = ask("read", on, path)
  if acting() and isinstance(got, Text) and (size := len(shown(got, show).encode())) > LARGEST:
    raise Refused(f"{path} shows {size} bytes, over {LARGEST}")
  show == HIDDEN or tell(on, path, got, show)
  return got


def write(text: Text, on="") -> Text:
  got = ask("write", on, Text(text.path, text.content))
  tell(on, text.path, got, differs(text.lines))
  return got


def turns(on="") -> list[tuple]:
  past, user, sent = [], [], []
  for it in reading(on):
    match it:
      case ("reply", *_):
        sent += user
        user = []
      case ("done", about, _, [*_] as turn) if question(("reply", about)):
        past += [("user", "\n\n".join(sent), None, None), turn]
        sent = []
      case ("tell", *_, notes):
        user.append("\n".join(notes))
  return [*past, ("user", "\n\n".join(sent + user), None, None)]


def module(on="") -> dict:
  return (transcript(on, "module") or [[{}] * 4])[-1][3]


def program(on="") -> dict[str, str]:
  words = {}
  for x in reading(on):
    match x:
      case ("module", *_):
        words = {}
      case ("run", *_, which, word, donor):
        words[donor or which] = word
  return words


def standing():
  return answer("stand", ROOT, [])


def operated(where):
  return where.split("/")[0] == OPERATOR


def stand(on=""):
  isinstance(got := peek(a := act("stand", on, None)), list) and tell(on, roster=got[0], actor=got[2])
  return a


def clock(on="") -> float:
  return ask("clock", on)


def chance(on="") -> float:
  return ask("chance", on)


def cd(path: str, on=""):
  path = ask("cd", on, path)
  tell(on, path)
  return path


def cwd(on="") -> str:
  return answer("cd", on, "")


def pause(id: str, why=None):
  if question(("rung", who := acting())) and covers(("pause", id), who):
    raise Refused(f"{who} cannot pause itself through {id}")
  control("pause", "paused", id, why)


def wake(id: str):
  control("wake", "woke", id)


def cancel(id: str, why=None):
  control("cancel", "cancelled", id, why)


def close(value: object, id=""):
  match get(who := acting()):
    case ("rung", _, by, _, _, back, *_):
      if back:
        raise CancelledError()
      id = id or by * prompted(by)
  match get(id := id or who):
    case ("prompt", _, _, on, shape, *_) if not isinstance(value, BaseException):
      try:
        s = eval(shape, module(on)) or object
        assert any(
          value in [a for a in x.__args__ if type(a) is type(value)]
          if (origin := getattr(x, "__origin__", x)) is Literal
          else isinstance(value, origin)
          for x in (s.__args__ if isinstance(s, type(int | str)) else [s])
        )
      except Exception:
        raise Refused(repr(value) + " not " + shape) from None
  left = [
    x
    for x in listening()
    if prompted(id)
    and x != id
    and under(x, id)
    and get(x)[0] in ("bash", "prompt")
    and not (over(x) or any(covers(c, x) for c in transcript(x, "cancel") + transcript(x, "close")))
  ]
  if left and under(who, id):
    raise Refused(f"{id} runs {left}: await or cancel each")
  [cancel(x) for x in left]
  control("close", "closed", id, value)
  if under(who, id):
    raise CancelledError()


def debug(template: Template):
  text = "".join(
    x if isinstance(x, str) else format(("%" + x.conversion) % (x.value,) if x.conversion else x.value, x.format_spec)
    for x in template
  )
  (who := acting()) and tells(who) and text and say(*told(who, "debugged", debug=text))


def wait(seconds: float = 0, *acts: str, on="") -> Act[str | None]:
  if not acts:
    raise Refused("no act: await the act, or wait(seconds, act)")

  def ear(id):
    while not (got := list(filter(over, acts))):
      yield {id, *acts}
    yield "done", id, got[0]

  return act("wait", on, controlled(ear), seconds, *acts)


def rung(word="", retells="", to="", on="") -> Act:
  def ear(id):
    yield "started", id
    mine = {retells, scope(id)}
    if word:
      while (c := crafted(id)) and c[0] not in lineage(id):
        yield {"rung"}
      if to:
        act("reply", "", lambda r: (yield "done", r, ("assistant", word, None, None)), to)
      elif tells(id):
        yield "tell", id, [word]
      while not over(retells) and get(retells) if retells else paused(get(id)[2]):
        yield mine
      yield "ready", id, word
    while True:
      match (yield mine):
        case ("done", about, _, value) if question(("reply", about)) and get(about)[2] == id and not word:
          yield ("done", id, value) if isinstance(value, BaseException) else ("ready", id, value[1])
        case ("wants", about, by, _, call) if get(by)[4] == id:
          yield "started", about
          while not over(call):
            yield {call}
          yield "done", about, peek(call)
        case ("done", about, _, value) if question(("run", about)) and get(about)[4] == id:
          if isinstance(value, CancelledError):
            if retells:
              value = None
            elif tells(id):
              yield told(id, "cancelled")
          elif isinstance(value, BaseException):
            module()["raised"] = value
            if tells(id):
              yield told(id, "raised", raised=value)
          yield "done", id, value

  return act("rung", on, controlled(ear), word, retells, to if word or to else module(on).get("actor", ""))


def prompt[T](shape: type[T] | object, message="", to="", on="") -> Act[T]:
  named = (
    shape if isinstance(shape, str) else re.sub(r"""<class '|'>|('[^']*'|"[^"]*")|[\w.:/]*\.""", r"\1", repr(shape))
  )
  thread = on * prompted(on)
  if thread and not get(thread):
    raise Refused("no thread " + thread)
  to = to or (thread and "".join(get(thread)[6:]))
  asks = (to or module(on).get("actor")) != OPERATOR
  says = asks and thread and named == "None" and not over(thread)

  def ear(id):
    if asks:
      yield "started", id
      while crafted(id):
        yield {"rung"}
    yield opened(id, named, message=message, thread=thread)
    ready = asks
    while not says:
      if ready and not paused(id):
        rung(to=to)
        ready = False
      yield {id}
    yield "done", id, None

  return act("prompt", on, controlled(ear), named, message, to)


def chain(label="", source="", filter: Filter | list[str] | None = None, on="") -> Act[Never]:
  if scope(source) != source:
    raise Refused("no chain " + source)
  kept = (
    filter
    if filter is None or isinstance(filter, list)
    else [one[1] for one in filter([x for x in reading(source or ROOT) if question(x)])]
  )

  def ear(id):
    t = reading(o := source or ROOT)
    h = [(x[0] == "tell" and x[3][0].splitlines()[0]) or x[0] for x in t] + ["chain()", "#" + o, "setup"]
    hi = h.index("#" + o, lo := h.index("chain()"))
    hi *= hi < len(t)
    running, waiting, last, heard, held, due = set(), {}, standing(), [], {}, set()
    barren, wrote, inbox, owed, took, awaited, did = {}, {}, {}, {}, {}, {}, {}
    step = reply = note = to = ""
    stood = module(source or get(id)[3]).get("actor", last and last[2])

    def placed(went):
      return rung("stand()" + (went and "\ncd(" + repr(went) + ")"), to=stood)

    def seeded():
      went = placed(last[1])
      if last[4:]:
        rung('debug(t"{standing()[4]=}")', to=stood)
        rung(f"read({last[3]!r})", to=stood)
        for k in range(1 + (id == ROOT)):
          k and (yield "setup", id)
          for x in last[4]:
            x[1] and x[3] == k and rung(f"rung(read({x[1]!r}, HIDDEN).content)", to=stood)
          for y in last[4]:
            y[3] == k and y[2] and rung(y[2], to=stood)
      return went

    def thread(of):
      return next((g for g in lineage(of) if prompted(g)), "")

    def heed(of):
      if of in barren:
        due.add(of)
        barren[of] = 0
        wrote.pop(of, 0)

    def bind(whose):
      w = "\n\n".join(heard)
      heard.clear()
      return w and act("run", id, None, n := whose + "_told", unquoted(ladder.setdefault(n, w)), "")

    def replay(of="", words=""):
      fresh = not of
      for whose, said in list(ladder.items()):
        if under(whose, of):
          if (words + "\n").startswith(said + "\n"):
            words = words[len(said) + 1 :]
          else:
            fresh = True
            del ladder[whose]
            cancel(whose)
      if fresh:
        yield "module", id, {**globals(), "__name__": id, "actor": stood}
        for whose, said in ladder.items():
          said and rung(said, whose)
      if words:
        with site.set(of):
          rung(words)

    if source or "stand" in h[lo:hi]:
      kin = {
        source,
        id,
        *[n for one in ([x[1] for x in t if question(x)] if kept is None else kept) for n in lineage(one)],
      }
      later = {x[1] for x in t[h.index("setup") :] if question(x) and (not get(x[2]) or x[:3:2] == ("rung", ROOT))}
      later |= {x[1] for x in t if x[0] == "run" and not later.isdisjoint(lineage(x[4]))}
      yield (
        "prefix",
        id,
        [
          it
          for n, it in enumerate(t)
          if (lo <= n < hi and later.isdisjoint(lineage(it[1])))
          or (source and (not (b := get(it[1])) or (b[2] if b[0] == "reply" else it[1]) in kin))
        ],
      )
    ladder = {x: w for x, w in program(source or id).items() if over(x) or not get(x)}
    yield "started", id

    def opening():
      return opened(
        id,
        "Never",
        label=label,
        source=source,
        actor=stood * (not source),
        actor_via=(not source) * (get(id)[3] or "stand"),
      )

    top = opening()
    if last and (source or not last[3:]):
      yield top
      top = ""
    yield from replay()
    seat = top and last and (transcript(id, "stand") or (yield from seeded()))
    while True:
      r = get((a := (yield {id, "stand", "reply"}))[1]) or a
      match a:
        case ("done", *_) if r[0] == "stand" and standing() != last:
          was, last = last, standing()
          if last[2:3] != was[2:3]:
            stood = module()["actor"] = last[2]
            top = top and opening()
          if not was:
            top and (yield ("tell", id, ["chain()"]) if last[3:] else top)
            top *= bool(last[3:])
            if last[4:] and top and id == ROOT and not transcript(id, "reply"):
              seat = yield from seeded()
          elif last[3:] and not top:
            placed(
              last[1] * (was[1] != last[1]) * all(get(x[2]) and all(get(x[2])[4::2]) for x in transcript(id, "cd"))
            )
        case ("done", _, by, Refused() as why) if (
          r[0] == "reply"
          and r[3] != id
          and (paused(r[3]) or not by)
          and scope(maker := (get(p := get(r[2])[2]) or a)[2]) == id
        ):
          yield "tell", maker, [headed(p, "paused", why=why)]
          heed(thread(maker))
        case ("prompt", m, by, p, "None", *_) if p in barren and thread(by) != p:
          heed(p)
          operated(by) and inbox.setdefault(p, []).append(m)
        case ("pause", about, by, _) if scope(by) != id == scope(about):
          heed(thread(r[2]))
        case ("close" | "cancel", about, by, *_) if r[2] in running or thread(by) == held.get(about):
          held.pop(about, 0)
        case ("done", about, _, value) if (
          about in held
          and scope(maker := r[2]) == id
          and not prompted(maker)
          and not any(about in (c, *get(c)[5:]) for c in awaited.values())
        ):
          if maker in running or (maker in waiting and not isinstance(value, Exception)):
            value is None or did[maker].add("tell")
          else:
            scope(about) != id and (yield "tell", maker, [headed(about, "done", value=value)])
            heed(held[about])
      a[0] == "wake" and [heed(x) for x in barren if covers(a, x)]
      if a[2] in did:
        did[a[2]].add("close" if a[0] == "prompt" and operated(a[6]) else a[0])
      if a[0] in ("prompt", "rung") or (a[0] == "started" and not get(a[2]) and r[0] != "reply"):
        held[a[1]] = thread(r[2])
      elif a[0] == "done":
        held.pop(a[1], 0)
      if scope(a[1]) != id:
        continue
      if a[0] in ("ready", "done"):
        waiting.pop(a[1], None)
      if a[0] == "rung":
        did[a[1]] = set()
      if a[0] == "done" and r[0] == "rung" and (p := r[2]) in barren and not isinstance(a[3], CancelledError):
        kinds, debt = did[a[1]], owed.get(p, [])
        if "close" in kinds:
          debt = owed[p] = [x for x in debt if x not in took.get(a[1], [])]
        broke, waited, word = isinstance(a[3], Exception), a[1] in awaited, ladder.get(a[1])
        busy, written = p in held.values(), wrote.setdefault(p, [])
        barren[p] = (barren[p] + 1) * bool(
          broke
          or debt
          or (not waited and (word in written or kinds <= {"started", "ready", "done", "reply", "tell", "ran"}))
        )
        written.append(word)
        if barren[p] // 3:
          (debt or not busy) and pause(p, debt or "made nothing")
        elif debt or broke or waited or "tell" in kinds or not busy:
          due.add(p)
      match a:
        case ("carried", *_):
          top = ""
        case ("read", about, by, _, path) if prompted(path) and scope(path) == id:
          yield "done", about, Text(path, "\n".join(w for x, w in ladder.items() if x != by and under(x, path)))
        case ("write", about, by, _, Text(path, content) as text) if prompted(path) and scope(path) == id:
          under(by, path) and ladder.pop(by, None)
          yield from replay(path, content.rstrip("\n"))
          yield "done", about, text
        case ("read", about, *_, path) if (door := re.fullmatch(r"(bash\d+)/(stdout|stderr)", path)) and get(door[1]):
          yield (
            "done",
            about,
            getattr(
              peek(door[1]),
              door[2],
              Text(path, "".join(x[3] for x in transcript(door[1], "out") if x[1::3] == door.groups())),
            ),
          )
        case ("done", *_) if top and r[0] == "rung" and not crafted(id):
          if seat:
            yield top
            top = ""
          else:
            seat = placed(last[1])
        case ("rung", rid, by, _, "", *_):
          waiting[rid] = ""
          prompted(by) and not over(by) and barren.setdefault(by, 0)
        case ("tell", about, by, notes) if notes not in (["chain()"], [*r[4:5]]):
          heard.append("\n".join(notes))
          if a is note:
            note = bind(step)
        case ("done", about, *_) if about == note and step in waiting:
          if (p := get(step)[2]) in barren:
            due.discard(p)
            took[step] = [*inbox.get(p, [])]
          with site.set(step):
            waiting[step] = reply = act("reply", id, controlled(idle), to)
        case ("ready", rid, _, word):
          if rid in took:
            inbox[p := r[2]] = inbox.get(p, [])[len(took[rid]) :]
            took[rid] = owed[p] = owed.get(p, []) + took[rid]
          rid == step or bind(rid)
          ladder[(donor := r[5]) or rid] = word
          act("run", id, None, rid, unquoted(word), donor)
          running.add(rid)
        case ("done", _, "", Refused() as why) if r[0] == "reply":
          pause(id, why)
        case ("done", about, *_) if about in barren:
          due.discard(about)
          for fold in (barren, owed, wrote):
            fold.pop(about, None)
          for message in inbox.pop(about, []):
            with site.set(message):
              rung(to=r[6])
      if r[0] == "wants":
        rid = get(r[2])[4]
        running.discard(rid) if a[0] == "started" else running.add(rid)
        if a[0] == "wants" and not over(r[4]):
          awaited[rid] = r[4]
      elif a[0] == "done":
        running.discard(a[1])
        for fold in (took, awaited, did):
          fold.pop(a[1], None)
      if running:
        continue
      if (step not in waiting or paused(step)) and (
        (got := next((x for x in waiting if not (paused(x) or over(x) or waiting[x])), "")),
        step := got or step * (step in waiting),
      )[0]:
        maker, to = get(step)[2::4]
        if offered(last[0], to) is None:
          close(Refused(to + " no actor"), maker * prompted(maker) or step)
        else:
          note = yield told(
            step,
            "advance on " + maker,
            share=filled(reply) or None,
            waits=[c for c in awaited.values() if not over(c)] or None,
          )
      for lone in [x for x in due if not (over(x) or paused(x) or x in {get(y)[2] for y in waiting})]:
        with site.set(lone):
          waiting[rung(to=get(lone)[6])] = ""

  return act("chain", on, ear, label, source, *[kept] * (kept is not None))


def grant(usd: float | None = None, share: float | None = None, on="") -> Act[None]:
  def ear(id):
    here = scope(id)
    if not ((usd or share) and (usd or 0) >= 0 <= (share or 0) <= 1):
      yield "done", id, Refused(f"{usd}/{share} no ceiling")
      return
    yield "started", id
    spent = 0
    for x in transcript(here, "grant"):
      x[3] != here or x[1] == id or close(None, x[1])
    yield opened(id, "None", usd=usd, share=share)
    while True:
      match (yield {id, here}):
        case ("done", about, _, (_, _, (*_, cost), _)) if question(("reply", about)):
          spent += cost
          yield told(id, "ledger", spent=spent)
          if (usd and spent >= usd) or (share and (filled(about) or 0) >= share):
            pause(here, "ceiling")

  return act("grant", on, controlled(ear), usd, share)


def bash(
  command: str, stdin: str | None = "", timeout=TIMEOUT, ok=None, show: Show = TAIL, show_err: Show | None = None, on=""
) -> Act[Exit]:
  if any(map(callable, (ok, show, show_err))):
    raise Refused("no callable")

  def ear(id):
    yield opened(id, "Exit", command="" if show == HIDDEN else command)
    while True:
      match (yield {id, "merged"}):
        case ("merged", qid, *_, about) if about == id:
          yield "done", qid, show_err is None
        case ("done", about, _, got) if about == id:
          match got:
            case Exit(code, out, err) if show != HIDDEN:
              yield told(
                id,
                f"timed out after {timeout}s" if code is None else f"exited {code}",
                stdout=cut(shown(out, show or TAIL)),
                stderr=show_err and cut(shown(err, show_err)),
              )
          return

  def cut(text, most=LARGEST // 16):
    return text if len(text) <= 2 * most else text[:most] + f"\n... ({len(text)} chars)\n" + text[-most:]

  return act(
    "bash",
    on,
    controlled(ear, True),
    command,
    stdin,
    timeout,
    ok,
    *(show, show_err) * ((show, show_err) != (TAIL, None)),
  )


@dataclass
class Text:
  path: str
  content: str = ""
  before = None

  @property
  def lines(self) -> list[str]:
    return self.content.splitlines()

  def edit(self, lo: int, hi: int, text: str) -> Text:
    now = (self.content + "\n").splitlines(True)[: len(self.lines)]
    if not 1 <= lo <= hi + 1 <= len(now) + 1:
      raise Refused(f"{self.path} no lines {lo}:{hi}")
    now[lo - 1 : hi] = [text and text.removesuffix("\n") + "\n"]
    return self.replace(self.content, "".join(now))

  def replace(self, old: str, new: str, count=-1) -> Text:
    if old not in self.content:
      raise Refused(self.path + " no " + repr(min(old.splitlines(), key=lambda line: self.content.count(line))))  # noqa: PLW0108
    (made := Text(self.path, self.content.replace(old, new, count))).before = self
    return made

  def undo(self, n=1) -> Text:
    for _ in range(n):
      self = self.before or self  # noqa: PLW0642
    return self

  def append(self, text: str) -> Text:
    return self.insert(len(self.lines) + 1, text)

  def insert(self, line: int, text: str) -> Text:
    return self.edit(line, line - 1, text)

  def delete(self, lo: int, hi: int) -> Text:
    return self.edit(lo, hi, "")


@dataclass
class Exit:
  code: int | None
  stdout: Text
  stderr: Text


class Act[T = object](str):
  def __await__(self) -> Generator[object, Any, T]:
    return (yield self)


class Refused(Exception): ...


class Overflow(Refused): ...


class Drift(Exception): ...


def lineage(name):
  yield name
  while a := get(name):
    yield (name := a[2])


def under(name, of):
  return "" != of in lineage(name)


def acting():
  return site.get() * bool(get(site.get()))


def prompted(name):
  return question(("prompt", name))


def question(a):
  return bool(re.fullmatch(a[0] + r"\d+", a[1]))


def scope(name):
  while (a := get(name)) and a[0] != "chain":
    name = a[3]
  return name * bool(a)


def tell(on, path="", got=None, show=HEAD, **words):
  (who := acting()) and tells(who) and say(
    *told(
      transcript(on, who)[-1][1],
      path=path,
      **words,
      **{
        "numbers": at if (at := picked(show, got.lines)) and at[-1] - at[0] >= len(at) else None,
        "text": shown(got, show),
      }
      if isinstance(got, Text)
      else {"value": got},
    )
  )


def answer(kind, on, empty):
  return next((got for x in reversed(transcript(on, kind)) if isinstance(got := peek(x[1]), type(empty))), empty)


def filled(about):
  match peek(about):
    case (_, _, (tokens, *_), _):
      return round(tokens / (offered(standing()[0], get(about)[4]) or WINDOW), 2)


def over(id):
  return peek(id, ...) is not ...


def tells(id):
  return get(id)[2] != scope(id) or all(get(id)[4::2])


def crafted(id):
  return [x[1] for x in transcript(id, "rung") if all(x[4::2]) and not over(x[1])]


def told(id, what="", *notes, **words):
  return "tell", id, [headed(id, what, **words), *notes]


def control(kind, name, id, *words):
  if not get(id):
    raise Refused("no act " + repr(id))
  over(id) or scope(acting()) == scope(id) or (kind == "wake" and not paused(id)) or say(
    *told(id, name + " by " + site.get(), value=(*words, None)[0])
  )
  return say(kind, id, *words)


def headed(id, what="", **words):
  text = f"#{id} {what}".rstrip()
  for word, value in words.items():
    name = id + "_" + word
    if isinstance(value, str) and "\n" in value:
      while "</s:" + name + ">\n" in value + "\n":
        name += "_"
      text += f"\n<s:{name}>\n{value}</s:{name}>"
    elif value not in (None, ""):
      text += f"\n{name} = " + re.sub(r"^[\w.]+\.(?=[A-Z]\w*\()", "", repr(value))
  return text


def opened(id, of, **words):
  return told(id, "", id + ": Act[" + of + "] = Act(" + repr(id) + ")", **words)


def shown(text, show):
  lines = text.lines
  return "\n".join(x[:1000] + f"... ({len(x)} chars)" if (x := lines[i - 1])[1000:] else x for i in picked(show, lines))


def unquoted(word):
  made, at, odd = [], 0, set()
  for o in re.finditer(r"(?m)^<s:(\w+)>\n?", word):
    if o.start() >= at and o[1] not in odd:
      if m := re.compile("(?m)</s:" + o[1] + ">$").search(word, o.end()):
        made += [
          word[at : o.start()],
          o[1] + " = " + repr(word[o.end() : m.start()]) + "\n" * word.count("\n", o.start(), m.end()),
        ]
        at = m.end()
      else:
        odd.add(o[1])
  return "".join(made) + word[at:]


def offered(roster, to):
  return next((x[2] for x in roster if to in (x[0], *[x[0] + "/" + e for e in x[1]])), None)


def covers(a, id):
  kind, of, *_ = a

  def on(name):
    while name != of and prompted(name):
      name = get(name)[3]
    return name == of

  if kind == "close":
    if question(("reply", id)):
      id = get(id)[2]
    return on(id) or (question(("rung", id)) and on(get(id)[2]))
  return any(map(on, lineage(id))) or scope(id) == of


def paused(id):
  return next((x[0] == "pause" for x in reversed(transcript(id, "pause")) if covers(x, id)), False)


def idle(id):
  while True:
    yield {id}


def lives(g, a):
  try:
    while isinstance(a := g.send(a), tuple):
      a = say(*a)
  except StopIteration:
    return False
  return a


def controlled(ear, lasting=False):
  def lived(id):
    g, later, halt = ear(id), [], paused(id)
    w = lives(g, None)
    while w is not False:
      a = later.pop(0) if later and not halt else (yield w)
      if over(id) and not lasting:
        return
      match a:
        case ("pause" | "wake", *_) if covers(a, id) and (halt := a[0] == "pause"):
          pass
        case ("cancel" | "close", _, by, *_) if covers(a, id) and not (over(id) or (halt and under(by, id))):
          yield (
            "done",
            id,
            CancelledError(*filter(None, a[3:])) if a[0] == "cancel" else a[3] if a[1] == id else CancelledError(),
          )
        case _ if halt and get(a[1]) is not a:
          later.append(a)
        case _:
          w = lives(g, a)

  return lived


def boot(journal, **outside):
  global say, act, drive, get, peek, transcript, reading, listening, numbered, offers
  get_running_loop()
  made, known, done, held, cuts, log, alive, born, busy, left, heed, taken, top, upto = (
    Counter(),
    {},
    {},
    {},
    {},
    [],
    {},
    {},
    set(),
    [],
    {},
    set(),
    Counter(),
    {},
  )

  def numbered(kind, *words):
    top[kind] += 1
    return kind + str(top[kind])

  def say(kind, about, *words):
    a = (kind, about, site.get(), *words)
    if about in known and kind in ("started", "done"):
      taken.add(about)
      kind == "done" and done.setdefault(about, words[0])
    holds(on := scope(about), words[0] if kind == "prefix" else [a])
    if kind == "cut" and on:
      cuts[on] = words[0], len(held[on, ""])
    log.append((a, set()))
    dispatch()
    return a

  def act(kind, on, ear, *words):
    speaker = site.get()
    made[speaker, kind] += 1
    by = (question(("rung", speaker)) and known[speaker][5]) or speaker
    on = on or scope(speaker)
    if not on and kind != "chain":
      raise Refused("no chain for " + kind)
    if by and not (get(by) or by in outside or callable((module(on) or globals()).get(kind))):
      raise Refused(f"no verb {kind} on {on}, so a later life cannot make the act again")
    key = kind, by, made[speaker, kind]
    if key not in born:
      born[key] = numbered(kind, by, on, *words)
    a = (kind, name := born[key], by, on, *words)
    if known.setdefault(name, a) is a:
      holds(scope(on), [a])
      log.append((a, heard := set(outside) - busy))
      busy.add(id(a))
      try:
        for n, g in ears(a):
          ear or n in heard or n == "journal" or n in busy or name in taken or hear(n, g, a) or heard.add(n)
        if ear:
          heard.add(name)
          drive(ear(name), name)
        offers(a)
        if name not in taken and not busy & set(outside) & set(dict(ears(a))):
          with site.set(""):
            say("done", name, Refused("nothing takes " + kind))
      finally:
        busy.discard(id(a))
      dispatch()
    return Act(name)

  def offers(a):
    for n, g in outside.items():
      (a[1] in taken and a[0] != "chain") or n in busy or caught(n, g, a) or hear(n, g, a)

  def caught(n, g, a):
    for x in [*left]:
      x[0] == n and (left.remove(x), hear(*x))
    k = len(log)
    while k and log[k - 1][0] is not upto.get(n):
      k -= 1
    upto[n] = a
    for b, heard in log[k:]:
      if b is a:
        return
      n in heard or n not in dict(ears(b)) or heard.add(n) or hear(n, g, b)

  def ears(a):
    q = get(a[1]) or a[:1] * 4
    k = {a[0], *q[:4], *map(scope, q[2:4])}
    return sorted(
      (x for x in alive.items() if k & (heed.get(x[0]) or k) or a[0] in ("pause", "wake", "cancel", "close")),
      key=lambda x: (x[0] not in known, x[0] in outside),
    )

  def holds(on, facts):
    for x in on and facts:
      for k in {"", x[0].replace("wake", "pause"), x[2]}:
        held.setdefault((on, k), []).append(x)

  def dispatch():
    while not busy:
      if left:
        name, g, a = left.pop(0)
        hear(name, g, a)
      elif log:
        a, heard = log.pop(0)
        left.extend((*x, a) for x in ears(a) if x[0] not in heard)
      elif ((g := alive.get("journal")) and hear("journal", g, None)) or not log:
        return

  def hear(name, g, a):
    if name not in busy and alive.get(name) is g:
      with site.set(name):
        busy.add(name)
        try:
          heed[name] = w = lives(g, a)
          w is False and alive.pop(name)
        except (Exception, CancelledError) as fault:
          if name == "journal" or isinstance(fault, Drift):
            raise
          alive.pop(name)
          stop = isinstance(fault, CancelledError)
          if not (stop and over(name)):
            shut = [x[3] for x in transcript(name, "close") if stop and x[1] == name]
            say(
              "done" if get(name) and not over(name) else "dropped",
              name,
              (*shut, Refused(f"{name} raised {fault!r}"))[0],
            )
        finally:
          busy.discard(name)

  def drive(g, name):
    if name in alive:
      raise Refused(name + " hears")
    alive[name] = g
    hear(name, g, None)
    dispatch()

  def listening():
    return dict(alive)

  def get(about):
    return known.get(about)

  def peek(at, waiting=None):
    return done.get(at, waiting)

  def transcript(on="", of=""):
    return held.get((scope(on or site.get()), of), [])[:]

  def reading(on=""):
    kept, at = cuts.get(on := scope(on or site.get()), ([], 0))
    return [*kept, *held.get((on, ""), [])[at:]]

  for who, listener in [
    (OPERATOR, idle(OPERATOR)),
    *outside.items(),
    ("journal", journal(outside, known, taken, held, holds, log, left, top)),
  ]:
    drive(listener, who)
  root = Act(ROOT) if known else chain("root")
  stand(ROOT)
  return root

"""The record of a life, which stands outside the engine: journal gives the journal that boot takes, which keeps the
record of the life and says the record that it is given again, and fed gives that journal the entries that follow the
tip of a life that stands. gathered gives the data of a checkpoint at the tip of a life, and seed gives the entries
that a later life boots on from that data, so the build that opens a checkpoint, and not the one that wrote it, says
how its own journal makes each chain again.

The journal is the journal that the engine held, in its form. Boot gives it the tables of the life, and at its first
run it binds numbered, offers, drive and lives again in the names of its engine, each over the one that stood. A boot
binds numbered, offers and drive again, and lives is no name that boot binds, so the journal of the next life takes
the one that stood under the last journal. LIFE holds what one life of this process needs past the call that made its
journal: that pair of lives, the function that takes a tail, and the numbered of that journal, by which fed knows
that the life that stands is its own.

This interpreter imports it, and the sandbox of the crate loads it in a module of its own, as it loads the Kernel. Each
call is given the names of its engine, which it reads at each call and never holds, since boot binds the bus into the
engine. No model reads it, so it costs no token of the system prompt, and its contract, checkpoint.pyi, holds its types,
as the contract of the engine holds those of the engine.
"""

import re
from collections import Counter

LIFE = {}


def journal(names, record=()):
  site, question, scope, covers, over, module, acting, drifted, refused = (
    names[x] for x in ("site", "question", "scope", "covers", "over", "module", "acting", "Drift", "Refused")
  )
  record = [*record]
  first, owned, pending = {e[1]: e for (e,) in record[::-1] if e[0] in ("started", "done")}, set(), {}
  due = [e for (e,) in record[::-1] if first.get(e[1]) is not e]
  ranks = {id(e): n for n, (e,) in enumerate(record)}
  saved, again = {e[1]: e for (e,) in record if question(e)}, {}
  asked, strays, back = {}, {}, []

  def ear(outside, known, taken, held, holds, log, left, top, a=(), last=None):
    say, act, get, drive, counted, offers, carried, transcript = (
      names[x] for x in ("say", "act", "get", "drive", "numbered", "offers", "lives", "transcript")
    )
    if carried is LIFE.get("lives"):
      carried = LIFE["carried"]

    def holding(quest):
      top[quest[0]] = max(top[quest[0]], int(quest[1][len(quest[0]) :]))
      asked.setdefault(quest[:3:2], []).append((quest[1], quest[3:]))

    def more(entries):
      fresh = []
      for (e,) in entries:
        ranks[id(e)] = len(ranks)
        if e[0] in ("started", "done") and e[1] not in first and e[1] not in known:
          first[e[1]] = e
        else:
          fresh.append(e)
        if question(e) and saved.setdefault(e[1], e) is e:
          holding(e)
      due[:0] = fresh[::-1]

    for one in saved.values():
      holding(one)

    def drift(name, fact=None):
      ours, name = fact or get(name), strays.get(name) or name
      return drifted(
        f"{name} drifts: the life made {ours or 'no act'!s:.300}, the record holds {(fact and first[fact[1]]) or saved[name]!r:.300}"
      )

    def matched(sort, maker="", *said):
      ahead = asked.get((sort, maker), [])
      at = next((n for n, x in enumerate(ahead) if x[1] == said), None)
      if at is None:
        strays[name := counted(sort)] = ahead[0][0] if ahead else None
        return name
      return ahead.pop(at)[0]

    def numbered(kind, *said):
      name = matched(kind, *said)
      name in known or upto(saved.get(name))
      return name

    def owed():
      while due and question(x := due[-1]) and x[1] in known:
        due.pop()
      return due

    def upto(entry):
      while owed() and not question(x := due[-1]) and ranks[id(x)] < ranks.get(id(entry), 0):
        recount(due.pop())

    def repeat(kind, about, by, *words):
      with site.set(by):
        said = say(kind, about, *words)
      again[id(said)] = said
      held.setdefault((scope(about), "journal"), []).append(said)

    def recount(entry):
      match entry:
        case (kind, name, by, on, *words) if question((kind, name)):
          if (
            by in saved
            or (name not in first and by[-1:].isdigit())
            or (on and not get(on))
            or (by == "journal" and not holds(scope(on), [known.setdefault(name, (kind, name, by, on, *words))]))
          ):
            return
          if by not in outside and (not callable(verb := (module(on) or names).get(kind)) or by[-1:].isdigit()):
            raise drift(name)
          with site.set(by):
            try:
              act(kind, on, None, *words) if by in outside else verb(*words, on=on)
            except refused:
              pass
        case ("carried", about, _, _, values, definitions, *_):
          repeat(*entry)
          bind(module(about), about, values, definitions)
        case ("cut", about, "journal", turns, lost, cut):
          lost = [n for n in lost if n not in module(about)]
          note = f"The life goes on from a checkpoint. It lost {lost or 'no name'}, and it cut {cut or 'no act'}."
          repeat("cut", about, "journal", [*turns, *[("tell", about, "journal", [note])][: bool(lost + cut)]])
        case (_, about, *_) if scope(about):
          repeat(*entry)
        case (_, about, by, *_) if by in outside and about in saved and get(saved[about][3]) and not get(about):
          raise drift(about)

    def offered(made):
      kind, name = made[:2]
      if saved.get(name, made) == made:
        if name not in taken and (f := first.get(name)):
          if f[0] == "started":
            pending[name] = f
          upto(f)
          repeat(*f)
          while name in pending and owed() and due[-1][0] == "joined" and due.pop() and due:
            recount(due.pop())
        if kind in ("run", "chain") or not owed() or strays.get(name, name) is None:
          offers(made)

    def driven(g, name):
      fresh = acting() and name not in owned
      fresh and owned.add(name)
      try:
        drive(g, name)
      except refused:
        fresh and owned.discard(name)
        raise

    def lives(g, heard):
      if heard and again.get(id(heard), 0) is heard and heard[2] and site.get() not in known:
        heard = (*heard[:2], "journal", *heard[3:])
      return carried(g, heard)

    def flying():
      for x in [*taken]:
        if not over(x) and any(f[1] == x and f[2] in outside for f in held.get((scope(x), "started"), ())):
          pending[x] = ()
      return [*pending]

    LIFE.update(lives=lives, carried=carried, more=more, numbered=numbered, flying=flying)
    names.update(numbered=numbered, offers=offered, drive=driven, lives=lives)
    try:
      while True:
        while owed() and (
          not (log or left)
          or (due[-1][0] == "joined" and not question(due[-2]) and due.pop() and due)
          or (a and a[::2] == ("wake", "journal") and due[-1][1] in taken and due[-1][2] in outside)
        ):
          recount(due.pop())
        while back and not owed():
          yield back.pop(0)
        b = a
        match a := (yield):
          case (kind, about, by, *_) if (
            (q := get(about)) and by != "journal" and (by or repr(first.get(about)) != repr(a))
          ):
            if not by and a != q and ((owed() and strays.get(about, 1)) or about in first):
              raise drift(about, about in first and a)
            if by not in known and by not in owned:
              glue = (
                b is last is not None
                and kind not in ("started", "done")
                and ("keep", "", (("joined", "", "journal", kind, about),))
              )
              if about not in saved:
                a is q and glue and back.append(glue)
                back.append(("keep", "", (saved.setdefault(about, q),)))
              if a is not q:
                glue and back.append(glue)
                back.append(("keep", "", (a,)))
              last = a
            elif a is q and about not in saved:
              back.append(("keep", "", (saved.setdefault(about, q),)))
            if kind == "wake" and not owed():
              for name in [x for x in pending if covers(a, x) and not over(x)]:
                del pending[name]
                taken.discard(name)
                offers(known[name])
        # The program of a born chain starts with its birth, so each module that a chain makes again, as a fork of a
        # born chain makes its own, takes the bind of the last fact carried of that chain, or of the chain it forks.
        if a and a[0] == "module":
          born = a[1]
          while not transcript(born, "carried") and get(born)[5]:
            born = get(born)[5]
          for x in transcript(born, "carried")[-1:]:
            x[5:] and bind(a[3], a[1], x[4], x[5])
    finally:
      for pile in log, left, due, first, saved, back:
        pile.clear()

  return ear


def bind(module, about, values, definitions):
  # The module of a chain at the tip, made again as data: each value from its text, each definition, then each value
  # that a definition bound again, while a value whose object the module still holds stays that object, which a
  # definition took. A value or a definition that raises loses only itself, which the cut of the birth names.
  bound = {}
  for word in [None, *definitions, None]:
    for k, text in values.items() if word is None else ():
      if k not in bound or module.get(k) is not bound[k]:
        try:
          module[k] = bound[k] = eval(text, module)  # noqa: S307
        except Exception:  # noqa: S110
          pass
    try:
      word and eval(compile(word, about, "exec"), module)  # noqa: S307
    except Exception:  # noqa: S110
      pass


def fed(names, entries):
  def poke():
    return
    yield

  if names["numbered"] is not LIFE.get("numbered"):
    why = "no journal of the checkpointer keeps this life, so nothing takes a tail"
    raise names["Refused"](why)
  LIFE["more"](entries)
  names["drive"](poke(), "tail")


def held(names):
  if names["numbered"] is not LIFE.get("numbered"):
    raise names["Refused"]("no journal of the checkpointer keeps this life, so it holds no act")
  return LIFE["flying"]()


def seed(names, data):
  root, operator = names["ROOT"], names["OPERATOR"]
  entries, numbers = [], Counter()

  def put(sort, called, *words):
    last = int(called[len(sort) :])
    entries.extend(((sort, f"{sort}{n}", root, ""),) for n in range(numbers[sort] + 1, last))
    numbers[sort] = max(numbers[sort], last - 1) + bool(words)
    words and entries.append(((sort, called, *words),))

  asking = {a["on"] for a in data["acts"] if "value" not in a}
  # The journal makes an act again only on a chain or an act that it knows when the entry comes, and each act with a
  # value comes before each open prompt. home gives each act that it makes again the chain that the act is on, a
  # chain being on itself, and the facts of each other act, as one with a value on an open prompt, stay in the
  # prefix.
  home = {c["id"]: c["id"] for c in data["chains"]}
  kinds = {c["id"]: "chain" for c in data["chains"]}
  for x in sorted(data["acts"], key=lambda a: "value" not in a):
    if x["on"] in home:
      home[x["id"]], kinds[x["id"]] = home[x["on"]], x["kind"]
  # The maker of each chain and each act that the data names stands in the fact carried of the chain that the act is
  # on, or of the first chain, since the seed makes each again as the operator or the journal.
  made = {c["id"]: {} for c in data["chains"]}
  for x in [*data["chains"], *data["acts"]]:
    "by" in x and made[home.get(x["id"], data["chains"][0]["id"])].update({x["id"]: x["by"]})
  # Each chain is made before any chain holds its prefix, so a chain with a source takes no turn of its source again.
  for c in data["chains"]:
    put("chain", c["id"], operator, c["on"], c["label"], c["source"])
  for c in data["chains"]:
    i = c["id"]
    definitions = [d] if isinstance(d := c["definitions"], str) else d
    kept = [
      t for t in c["turns"] if t[1] not in kinds or home[t[1]] != i or t[0] not in ("started", "done", kinds[t[1]])
    ]
    entries += [(("carried", i, "journal", c["turns"], c["values"], definitions, made[i]),), (("prefix", i, i, kept),)]
    (c["paused"] or i in asking) and entries.append((("pause", i, operator),))
  for x in data["acts"]:
    "value" in x and (
      put(x["kind"], i := x["id"], "journal", x["on"], *x.get("words", ())),
      entries.extend([(("started", i, "journal"),), (("done", i, "journal", x["value"]),)]),
    )
  for x in data["acts"]:
    "value" in x or (
      put("prompt", x["id"], operator, x["on"], x["shape"], x["message"], x["to"]),
      x["held"] and entries.append((("started", x["id"], x["held"]),)),
    )
  for kind, most in data["taken"].items():
    put(kind, f"{kind}{most + 1}")
  for c in data["chains"]:
    i, cut = c["id"], c["cut"] + [y["rung"] for y in c.get("again", ())]
    entries.append((("cut", i, "journal", c["turns"], c["lost"] + [*c["values"]], cut),))
    word = (
      f"if not get(acting())[5]:\n for __part in {c.get('lives', [])!r}:\n"
      "  try: await rung(__part)\n  except Exception as __raised: debug(t'{__raised!r}')\n"
      " say('cut', scope(acting()), "
      "[x for x in reading() if x[0] != 'tell' or not under(x[1], acting()) or x[3][0].startswith(f'#{acting()} debugged')])\n"
      " del __part"
    )
    c.get("lives") and put("rung", f"rung{numbers['rung'] + 1}", operator, i, word, "", "")
  return entries + [(("wake", y["id"], operator),) for y in data["chains"] if y["id"] in asking and not y["paused"]]


def gathered(names, define, floor):
  get, peek, over, scope, question, prompted, lineage, paused, root = (
    names[x] for x in ("get", "peek", "over", "scope", "question", "prompted", "lineage", "paused", "ROOT")
  )
  transcript, reading, module, program, standing, listening, refused = (
    names[x] for x in ("transcript", "reading", "module", "program", "standing", "listening", "Refused")
  )

  def literal(v, into=None):
    isinstance(v, str) and get(v) and into is not None and into.add(v)
    if isinstance(v, names["Act"]):
      return f"Act({str(v)!r})" * (into is not None)
    if isinstance(v, BaseException):
      return literal(v.args) and repr(v)
    if v is None or isinstance(v, (int, float, str, names["Text"], names["Exit"])):
      return repr(v) * (not (isinstance(v, float) and v - v))
    if not isinstance(v, (dict, list, tuple, set)):
      return ""
    pairs = v.items() if isinstance(v, dict) else [(y,) for y in v]
    s = [": ".join(made) if all(made := [literal(y, into) for y in pair]) else "" for pair in pairs]
    ends = "[]" if isinstance(v, list) else "()" if isinstance(v, tuple) else "{}"
    whole = (
      "set()"
      if isinstance(v, set) and not v
      else ends[0] + ", ".join(s) + "," * (ends == "()" and len(s) == 1) + ends[1]
    )
    return whole if all(s) else ""

  def number(called):
    return int(re.sub(r"^\D+", "", called) or 0)

  chains = [x for x in listening() if question(("chain", x))]
  made = {k: v for c in chains for x in transcript(c, "carried") for k, v in (x[6:] or [{}])[0].items()}

  def maker(called):
    return made.get(called, get(called)[2])

  asked = [*map(get, chains)] + [x for h in chains for x in transcript(h) if x is get(x[1])]
  cut = sorted((x[1] for x in asked if x[0] == "run" and not over(x[1]) and get(x[4])), key=number)
  gone = {x[4] for x in asked if x[0] == "wants" and x[2] in cut and prompted(x[4]) and not over(x[1])}
  values, lost, named = {}, {}, {x[1] for x in asked if x[0] in ("prompt", "bash")}
  for c in chains:
    values[c], lost[c] = {}, []
    for key, value in module(c).items():
      if not (key.startswith("__") or callable(value) or names.get(key, values) is value):
        try:
          text = literal(value, found := set())
        except RecursionError:
          text = ""
        if text:
          values[c][key] = text
          named |= found
        else:
          lost[c].append(key)
  taken = dict(floor)
  for one in asked:
    taken[one[0]] = max(taken.get(one[0], 0), number(one[1]))
  words = {y[2] for y in (standing()[4:5] or [()])[0]}
  borne = sorted(
    (x for x in named - gone if get(x)[0] in ("prompt", "bash", "read", "write", "wait", "cd", "chance")),
    key=lambda r: (get(r)[0], number(r)),
  )
  acts = []
  for one in [
    *[x[1] for x in transcript(root, "stand") if over(x[1])][-1:],
    *[x[1] for x in transcript(root, "clock") if isinstance(peek(x[1]), float)][-1:],
    *borne,
  ]:
    a = get(one)
    d = {"kind": a[0], "id": one, "on": a[3], "by": maker(one)}
    if prompted(one) and not over(one):
      acts.append(
        {
          **d,
          "shape": a[4],
          "message": a[5],
          "to": a[6],
          "held": next((x[2] for x in transcript(scope(one), "started") if x[1] == one and get(x[2]) is None), ""),
        }
      )
    elif over(one):
      literal(peek(one), set()) and acts.append({**d, "words": a[4:], "value": peek(one)})
    else:
      cut.append(one)
      acts.append({**d, "value": refused(one + " was interrupted: the life that ran it ended before it did")})
  out = []
  for c in chains:
    a, ended = get(c), {y[1] for y in transcript(c, "done")}
    saved = [
      x
      for x in reading(c)
      if x[0] not in ("module", "carried", "made")
      and literal(x, set())
      and (not question(x) or (x[0] == "reply" and x[1] in ended) or x[1] in borne)
    ]
    held = {*chains, *borne, *(x[1] for x in saved if question(x))}
    out.append(
      {
        "id": c,
        "by": maker(c),
        "on": a[3] * (a[3] in chains),
        "label": a[4],
        "source": a[5],
        "paused": paused(c),
        "turns": [x for x in saved if x[0] not in ("started", "done") or x[1] in held],
        "definitions": [
          *filter(None, [define(d) for x in transcript(c, "carried")[-1:] for d in (x[5:] or [()])[0]]),
          *filter(None, [define(w) for r, w in program(c).items() if get(r) and get(r)[2] != "extensions"]),
        ],
        "values": values[c],
        "lost": lost[c],
        "cut": [x for x in cut if scope(x) == c],
        "lives": [
          *dict.fromkeys(
            get(r)[4]
            for x in listening()
            if scope(x) == c
            for r in lineage(x)
            if question(("rung", r)) and get(r)[4] in words
          )
        ],
      }
    )
  return {"taken": taken, "chains": out, "acts": acts}

CAP = 40
BUDGET = 4096


def catchup(on: str = "") -> Act:
  def ear(id):
    yield "started", id
    here = scope(id)
    if here == ROOT:
      act("clock", here, None)
    while True:
      match (yield {id, "stand"}):
        case ("done", about, *_) if question(("stand", about)) and not question(("rung", get(about)[2])):
          if here == ROOT:
            act("clock", here, None)
          seen: dict[str, object] = {}
          for fact in reading(here)[::-1]:
            if fact[0] not in ("read", "write") or (fact[0] == "read" and str(fact[4]).endswith(("/", "\\"))):
              continue
            was = peek(fact[1])
            path = was.path if isinstance(was, Text) else str(fact[4])
            if path in seen:
              continue
            seen[path] = None
            if isinstance(was, Text) and "://" not in path and get(path.split("/")[0]) is None:
              try:
                now = read(path, HIDDEN, here).lines
              except Refused:
                seen[path] = "gone"
                continue
              lines = {i: now[i - 1] for i in picked(differs(was.lines), now)}
              lines |= dict.fromkeys(range(len(now) + 1, len(was.lines) + 1))
              seen[path] = len(lines) if len(lines) > CAP else lines or None
          clocks = [x for one in transcript(ROOT, "clock") if isinstance(x := peek(one[1]), float)][-2:] or [0.0]
          hours = (clocks[-1] - clocks[0]) / 3600
          changed: dict | list = {key: value for key, value in seen.items() if value}
          kept = len(changed)
          while True:
            paragraph = headed(here, "caught up", hours=round(hours, 1) if hours > 1 else None, changed=changed or None)
            if len(paragraph.encode()) <= BUDGET:
              break
            changed = [*changed][:kept]
            kept -= 1
          if "\n" in paragraph:
            yield "tell", here, [paragraph]

  return act("catchup", on, ear)

NAMES = ("AGENTS.md", "CLAUDE.md")
LOCAL = ("AGENTS.local.md", "CLAUDE.local.md")
HOME = 5


def lacking(known: set[str]) -> Show:
  return lambda lines: [i for i, line in enumerate(lines, 1) if line not in known]


def remembered(path: str) -> bool:
  return path.replace("\\", "/").rsplit("/", 1)[-1] in (*NAMES, *LOCAL)


def joined(folder: str, name: str) -> str:
  return folder + name if folder.endswith(("/", "\\")) else folder + "/" + name


def looked(path: str, on: str = "") -> Text | None:
  try:
    return read(path, HIDDEN, on)
  except Refused:
    return None


def pieces(path: str) -> list[str]:
  kept: list[str] = []
  for one in path.replace("\\", "/").split("/"):
    if one == ".." and kept and kept[-1] not in ("", ".."):
      kept.pop()
    elif one not in (".", "") or not kept:
      kept.append(one)
  return kept


def above_home() -> list[tuple[str, set[str] | None]]:
  home = pieces(str((standing()[HOME:] or [""])[0]))
  return [("/".join(home[:k]) or "/", None) for k in range(1, len(home))]


def folders(path: str = ".", on: str = "") -> list[tuple[str, set[str] | None]]:
  found: list[tuple[str, set[str] | None]] = []
  here = looked("./", on)
  if here is not None:
    parts = pieces(here.path)
    if parts[0] == "~":
      found += above_home()
    found += [("/".join(parts[:k]) or "/", None) for k in range(1, len(parts))]
    found.append((here.path, set(here.lines)))
    if "://" not in path:
      absolute = path.startswith(("/", "\\", "~")) or path[1:3] in (":/", ":\\")
      full = pieces(path if absolute else joined(here.path, path))
      held = here
      for one in full[len(parts) :] if full[: len(parts)] == parts else []:
        if one + "/" not in held.lines or (deeper := looked(joined(held.path, one + "/"), on)) is None:
          break
        found.append((deeper.path, set(deeper.lines)))
        held = deeper
  user = looked("config://", on)
  return [*([(user.path, set(user.lines))] if user else []), *found]


def memory(path: str = ".", on: str = "") -> list[Text]:
  was: dict[str, list[str]] = {}
  held: set[str] = set()
  for x in reading(on):
    match x:
      case ("done", about, _, Text(place, content)) if (
        (question(("read", about)) or question(("write", about))) and get(maker := get(about)[2]) and tells(maker)
      ):
        was[place] = content.splitlines()
        if remembered(place):
          held.add(content)
  got: list[Text] = []
  for folder, names in folders(path, on):
    for group in NAMES, LOCAL:
      found = None
      for entry in group:
        if (names is None or entry in names) and (found := looked(joined(folder, entry), on)) is not None:
          break
      if found is None:
        continue
      if found.content in held or any(one.path == found.path or one.content == found.content for one in got):
        continue
      got.append(found)
      mine = set(found.lines)
      near = max(was.values(), key=lambda kept: len(set(kept) & mine), default=[]) if found.path not in was else []
      if found.path in was:
        show = differs(was[found.path])
      elif mine and 2 * len(set(near) & mine) > len(mine):
        show = lacking(set(near))
      else:
        show = span(1, -1)
      tell(on, found.path, found, show)
  return got


async def recall(on: str = "") -> Act:
  return remember(on)


def visited(id: str, before: set[str], about: str, got: object) -> str:
  made = get(about)
  if made is None or made[0] not in ("read", "write", "cd") or scope(about) != scope(id) or about in before:
    return ""
  if not question(("rung", made[2])) or (made[0] == "read" and str(made[4]).endswith(("/", "\\"))):
    return ""
  text = made[4] if made[0] == "write" and isinstance(got, Text) else got
  path = text if isinstance(text, str) else getattr(text, "path", "")
  return "" if "://" in path or remembered(path) else path


def remember(on: str = "") -> Act:
  def ear(id):
    yield "started", id
    before = {x[1] for kind in ("read", "write", "cd") for x in transcript(on, kind)}
    memory(on=on)
    while True:
      match (yield {id, "read", "write", "cd", "stand"}):
        case ("done", about, _, got) if path := visited(id, before, about, got):
          memory(path, on)
        case ("done", about, *_) if question(("stand", about)) and not question(("rung", get(about)[2])):
          memory(on=on)

  return act("remember", on, controlled(ear))

def skills(on: str = "") -> Text:
  return read("skills://", on=on)


def skill(name: str = "", show: Show = HEAD, on: str = "") -> Act[Text]:
  def ear(id: str):
    yield opened(id, "Text", name=name)
    while True:
      match (yield):
        case ("done", about, _, got) if about == id:
          if isinstance(got, Text):
            yield told(id, "done", text=shown(got, show))
          return

  return skill_made(Text, act("skill", on, controlled(ear, lasting=True), name))


def skill_made[T](_shape: type[T], made) -> Act[T]:
  return made


async def listed(on: str = "") -> None:
  skills(on)


def defined(*names: str) -> Show:
  def ident(text: str) -> str:
    size = 0
    while size < len(text) and (text[size].isalnum() or text[size] == "_"):
      size += 1
    return text[:size]

  def named(line: str) -> str:
    for prefix in ("async def ", "def ", "class ", "type "):
      if line.startswith(prefix):
        return ident(line[len(prefix) :])
    name = ident(line)
    return name if line[len(name) :].lstrip()[:1] in (":", "=") else ""

  def show(lines: list[str]) -> list[int]:
    out: list[int] = []
    at, start, decorated = 0, 0, False
    while at < len(lines):
      first = at
      at += 1
      while at < len(lines) and (not lines[at] or lines[at][0] in " \t)]}"):
        at += 1
      if lines[first].startswith("@") or (decorated and lines[first].startswith("#")):
        decorated = True
        continue
      decorated = False
      end = at
      while end > first + 1 and not lines[end - 1]:
        end -= 1
      if named(lines[first]) in names:
        out.extend(range(start + 1, end + 1))
      start = at
    return out

  return show

compaction = """Compaction cuts this chain to the work that it still needs, and the chain goes on under its name.
- supersede(keep) cuts this chain to what the filter keep kept, and every act. compact() supersedes this chain with a
  filter that applies FILTERS in order, and its next word binds the summary
  that it is given and reads again each file whose read or write it kept, showing what changed. Its prompts, its
  rungs, the words that run and its module go on.
- A filter drops acts. latest() keeps the last read or write of each path, quiet() drops the commands, recent(n)
  keeps the acts of the last n replies, and await chosen() asks the model of this chain which acts to keep.
  together(*filters) applies filters in order.
- choice() asks on this chain the model that wrote its last reply, which reads the chain from its cache, which acts
  the work still needs, and what the rest holds, as ids and a summary. The turn of that answer stays in the chain.
- await condense() compacts this chain at once to what choice() chose, with the summary of the model, as compacted()
  does once.
- clear() cuts this chain to nothing, with no summary: its model reads from zero, and the chain keeps its name, its
  module, its prompts and its threads.
- compacted() wraps a chain: after an answer that reads more than SHARE of the window, it asks choice(), and at the
  next reply once that came, it compacts the chain to what the model chose. It moves, stops and pauses nothing.
- fitted() watches a chain: when its model refuses a reply because the prompt passes its window, it cuts the chain at
  once to its open prompts, so the next reply reads less and the chain goes on with no pause.
- The life word wraps each chain with compacted() and fitted(), so a chain compacts with a summary of the model
  before it passes its window, and the cut of fitted() is the last resort.
- A project changes the defaults in a skill of its own, whose word rebinds SHARE, FILTERS or BRIEF."""
SHARE = 0.6
OVERFLOWED = """The model refused the last reply of this chain, since its prompt passed the window of the model,
so compaction cut the chain to its open prompts: read again what the work still needs."""
BRIEF = """The chain grows past its window, and it goes on with what the work still needs.
Choose what it keeps: each act that holds a decision or a ruling of the operator, a brief, a finding that the work
still needs, and the last state of each command that matters. A step keeps all that it made, and an act keeps the
step that made it. The chain keeps its module, its prompts and its steps, so keep no act for a value that the module
holds. It reads again each file whose read or write you keep and shows what changed since, so keep the last read or
write of each file that the work still needs, and no other.
Close this prompt with one call, close((ids, summary)): the ids to keep, as list[str], as ["read3", "bash7"], and a
summary, in a few short lines, of what the acts that you drop hold and the work still needs to know. Do no other work
in this word."""


def together(*filters: Filter) -> Filter:
  def keep(acts: list) -> list:
    for one in filters:
      acts = one(acts)
    return acts

  return keep


def latest() -> Filter:
  def keep(acts: list) -> list:
    last = {t.path: a[1] for a in acts if a[0] in ("read", "write") and isinstance(t := peek(a[1]), Text)}
    return [
      a for a in acts if a[0] not in ("read", "write") or a[1] in last.values() or not isinstance(peek(a[1]), Text)
    ]

  return keep


def quiet() -> Filter:
  return lambda acts: [a for a in acts if a[0] != "bash"]


def recent(n: int) -> Filter:
  def keep(acts: list) -> list:
    rungs = [a[2] for a in acts if a[0] == "reply"][-n:] if n > 0 else []
    return [a for a in acts if any(under(a[1], one) for one in rungs)]

  return keep


def choice(on: str = "") -> Act:
  here = on or scope(acting())
  wrote = [str(a[4]) for a in transcript(here, "reply") if isinstance(peek(a[1]), tuple) and not operated(str(a[4]))]
  return prompt("tuple", BRIEF, to=wrote[-1] if wrote else module(here)["actor"], on=here)


async def chosen(on: str = "") -> Filter:
  got = await choice(on)
  assert isinstance(got, tuple)
  return take(*got[0])


FILTERS: list[Filter] = [latest(), recent(8)]


regrounded: set[str] = set()


def reground(on: str = "") -> None:
  here = on or scope(acting())
  voiced = {x[1] for x in reading(here) if x[0] == "tell"}
  held: dict[str, tuple[Text, bool]] = {}
  for a in reading(here):
    if (
      a[0] in ("read", "write")
      and a[1] in voiced
      and isinstance(t := peek(a[1]), Text)
      and "://" not in t.path
      and get(t.path.split("/")[0]) is None
    ):
      held[t.path] = (t, a[1] in regrounded)
  for path, (text, again) in held.items():
    seen = {x[1] for x in transcript(here) if x[0] == "read"}
    try:
      read(path, HEAD if again else differs(text.lines), on=on)
    except Refused:
      continue
    regrounded.update(x[1] for x in transcript(here) if x[0] == "read" and x[1] not in seen)


def headline(fact: tuple) -> str:
  """The first line of the first note of a tell, or else the kind of the fact."""
  match fact:
    case ("tell", _, _, [str(first), *_]):
      return first.split("\n")[0]
  return str(fact[0])


def supersede(keep: Filter | None = None, on: str = "") -> str:
  here = on or scope(acting())
  theirs = reading(here)
  kin = {here}
  acts = []
  for x in theirs:
    match x:
      case (str(kind), str(name), str(by), str(where), *words) if question(x):
        acts.append((kind, name, by, where, *words))
  for one in keep(acts) if keep else acts:
    name = one[1]
    while name not in kin and (b := get(name)):
      kin.add(name)
      name = b[2]

  heads = [headline(fact) for fact in theirs]
  lo = heads.index("chain()") if "chain()" in heads else len(theirs)
  hi = heads.index("#" + here, lo) if "#" + here in heads[lo:] else lo
  setup = {id(fact) for fact in theirs[lo:hi]}

  def stays(it: tuple) -> bool:
    if id(it) in setup:
      return True
    made = get(it[1])
    if made is None:
      return it[2] in kin
    return question(it) or ((made[2] if question(("reply", it[1])) else it[1]) in kin and it[0] != "carried")

  say("cut", here, [it for it in theirs if stays(it)])
  return here


def compact(filters: list[Filter] | None = None, summary: str = "", on: str = "") -> str:
  here = supersede(together(*(FILTERS if filters is None else filters)), on)
  name = "summary"
  while f"</s:{name}>" in summary:
    name += "_"
  quoted = f"<s:{name}>\n{summary}</s:{name}>\n" if summary else ""
  rung(f"{quoted}reground()", on=here)
  return here


def clear(on: str = "") -> str:
  return supersede(lambda _: [], on)


def compacted(on: str = "") -> Act:
  def ear(id):
    yield "started", id
    here, pending, seen, refused = scope(id), "", set(), False
    chose: tuple | None = None

    def keeping(ids: list[str], after: set) -> Filter:
      return lambda acts: take(*ids, *[a[1] for a in acts if a[1] not in after])(acts)

    while True:
      match (yield {id, here} | ({pending} if pending else set())):
        case ("done", about, _, Refused() as why) if about == pending:
          pending, refused = "", True
          yield told(id, "kept the chain as it is", why=why)
        case ("done", about, _, value) if about == pending:
          chose = (None, "")
          match value:
            case ([*listed], str() as summary):
              chose = ([keeping([i for i in listed if isinstance(i, str) and scope(i)], set(seen)), latest()], summary)
        case ("done", about, *_) if (
          question(("reply", about)) and scope(about) == here and not (pending or chose or refused)
        ):
          if (filled(about) or 0) > SHARE:
            seen = {fact[1] for fact in transcript(here) if question(fact)}
            pending = str(choice(on=here))
        case ("reply", about, *_) if chose and question(("reply", about)) and scope(about) == here:
          compact(chose[0], summary=chose[1].strip(), on=here)
          pending, chose = "", None

  return act("compacted", on, controlled(ear))


def fitted(on: str = "") -> Act:
  def ear(id):
    yield "started", id
    here, row = scope(id), False
    while True:
      match (yield {id, here}):
        case ("done", about, _, Refused() as why) if question(("reply", about)) and scope(about) == here:
          if isinstance(why, Overflow) and not row:
            compact([lambda acts: [a for a in acts if a[0] == "prompt" and not over(a[1])]], OVERFLOWED, here)
          row = isinstance(why, Overflow)
        case ("done", about, _, tuple()) if question(("reply", about)) and scope(about) == here:
          row = False

  return act("fitted", on, controlled(ear))


async def condense(on: str = "") -> str:
  here = on or scope(acting())
  before = {fact[1] for fact in transcript(here) if question(fact)}
  match await choice(here):
    case ([*listed], str() as summary):
      ids = [i for i in listed if isinstance(i, str) and scope(i)]

      def chose(acts: list) -> list:
        return take(*ids, *[a[1] for a in acts if a[1] not in before])(acts)

      return compact([chose, latest()], summary.strip(), here)
  return compact(on=here)

