CAP = 40
BUDGET = 4096


def catchup(on: str = "") -> Act:
  def ear(id):
    yield "started", id
    here = scope(id)
    if here == ROOT:
      act("clock", here, None)
    while True:
      match (yield {id, "stand"}):
        case ("done", about, *_) if question(("stand", about)) and not question(("rung", get(about)[2])):
          if here == ROOT:
            act("clock", here, None)
          seen: dict[str, object] = {}
          for fact in reading(here)[::-1]:
            if fact[0] not in ("read", "write") or (fact[0] == "read" and str(fact[4]).endswith(("/", "\\"))):
              continue
            was = peek(fact[1])
            path = was.path if isinstance(was, Text) else str(fact[4])
            if path in seen:
              continue
            seen[path] = None
            if isinstance(was, Text) and "://" not in path and get(path.split("/")[0]) is None:
              try:
                now = read(path, HIDDEN, here).lines
              except Refused:
                seen[path] = "gone"
                continue
              lines = {i: now[i - 1] for i in picked(differs(was.lines), now)}
              lines |= dict.fromkeys(range(len(now) + 1, len(was.lines) + 1))
              seen[path] = len(lines) if len(lines) > CAP else lines or None
          clocks = [x for one in transcript(ROOT, "clock") if isinstance(x := peek(one[1]), float)][-2:] or [0.0]
          hours = (clocks[-1] - clocks[0]) / 3600
          changed: dict | list = {key: value for key, value in seen.items() if value}
          kept = len(changed)
          while True:
            paragraph = headed(here, "caught up", hours=round(hours, 1) if hours > 1 else None, changed=changed or None)
            if len(paragraph.encode()) <= BUDGET:
              break
            changed = [*changed][:kept]
            kept -= 1
          if "\n" in paragraph:
            yield "tell", here, [paragraph]

  return act("catchup", on, ear)

NAMES = ("AGENTS.md", "CLAUDE.md")
LOCAL = ("AGENTS.local.md", "CLAUDE.local.md")
HOME = 5


def lacking(known: set[str]) -> Show:
  return lambda lines: [i for i, line in enumerate(lines, 1) if line not in known]


def remembered(path: str) -> bool:
  return path.replace("\\", "/").rsplit("/", 1)[-1] in (*NAMES, *LOCAL)


def joined(folder: str, name: str) -> str:
  return folder + name if folder.endswith(("/", "\\")) else folder + "/" + name


def looked(path: str, on: str = "") -> Text | None:
  try:
    return read(path, HIDDEN, on)
  except Refused:
    return None


def pieces(path: str) -> list[str]:
  kept: list[str] = []
  for one in path.replace("\\", "/").split("/"):
    if one == ".." and kept and kept[-1] not in ("", ".."):
      kept.pop()
    elif one not in (".", "") or not kept:
      kept.append(one)
  return kept


def above_home() -> list[tuple[str, set[str] | None]]:
  home = pieces(str((standing()[HOME:] or [""])[0]))
  return [("/".join(home[:k]) or "/", None) for k in range(1, len(home))]


def folders(path: str = ".", on: str = "") -> list[tuple[str, set[str] | None]]:
  found: list[tuple[str, set[str] | None]] = []
  here = looked("./", on)
  if here is not None:
    parts = pieces(here.path)
    if parts[0] == "~":
      found += above_home()
    found += [("/".join(parts[:k]) or "/", None) for k in range(1, len(parts))]
    found.append((here.path, set(here.lines)))
    if "://" not in path:
      absolute = path.startswith(("/", "\\", "~")) or path[1:3] in (":/", ":\\")
      full = pieces(path if absolute else joined(here.path, path))
      held = here
      for one in full[len(parts) :] if full[: len(parts)] == parts else []:
        if one + "/" not in held.lines or (deeper := looked(joined(held.path, one + "/"), on)) is None:
          break
        found.append((deeper.path, set(deeper.lines)))
        held = deeper
  user = looked("config://", on)
  return [*([(user.path, set(user.lines))] if user else []), *found]


def memory(path: str = ".", on: str = "") -> list[Text]:
  was: dict[str, list[str]] = {}
  held: set[str] = set()
  for x in reading(on):
    match x:
      case ("done", about, _, Text(place, content)) if (
        (question(("read", about)) or question(("write", about))) and get(maker := get(about)[2]) and tells(maker)
      ):
        was[place] = content.splitlines()
        if remembered(place):
          held.add(content)
  got: list[Text] = []
  for folder, names in folders(path, on):
    for group in NAMES, LOCAL:
      found = None
      for entry in group:
        if (names is None or entry in names) and (found := looked(joined(folder, entry), on)) is not None:
          break
      if found is None:
        continue
      if found.content in held or any(one.path == found.path or one.content == found.content for one in got):
        continue
      got.append(found)
      mine = set(found.lines)
      near = max(was.values(), key=lambda kept: len(set(kept) & mine), default=[]) if found.path not in was else []
      if found.path in was:
        show = differs(was[found.path])
      elif mine and 2 * len(set(near) & mine) > len(mine):
        show = lacking(set(near))
      else:
        show = span(1, -1)
      tell(on, found.path, found, show)
  return got


async def recall(on: str = "") -> Act:
  return remember(on)


def visited(id: str, before: set[str], about: str, got: object) -> str:
  made = get(about)
  if made is None or made[0] not in ("read", "write", "cd") or scope(about) != scope(id) or about in before:
    return ""
  if not question(("rung", made[2])) or (made[0] == "read" and str(made[4]).endswith(("/", "\\"))):
    return ""
  text = made[4] if made[0] == "write" and isinstance(got, Text) else got
  path = text if isinstance(text, str) else getattr(text, "path", "")
  return "" if "://" in path or remembered(path) else path


def remember(on: str = "") -> Act:
  def ear(id):
    yield "started", id
    before = {x[1] for kind in ("read", "write", "cd") for x in transcript(on, kind)}
    memory(on=on)
    while True:
      match (yield {id, "read", "write", "cd", "stand"}):
        case ("done", about, _, got) if path := visited(id, before, about, got):
          memory(path, on)
        case ("done", about, *_) if question(("stand", about)) and not question(("rung", get(about)[2])):
          memory(on=on)

  return act("remember", on, controlled(ear))

def skills(on: str = "") -> Text:
  return read("skills://", on=on)


def skill(name: str = "", show: Show = HEAD, on: str = "") -> Act[Text]:
  def ear(id: str):
    yield opened(id, "Text", name=name)
    while True:
      match (yield):
        case ("done", about, _, got) if about == id:
          if isinstance(got, Text):
            yield told(id, "done", text=shown(got, show))
          return

  return skill_made(Text, act("skill", on, controlled(ear, lasting=True), name))


def skill_made[T](_shape: type[T], made) -> Act[T]:
  return made


async def listed(on: str = "") -> None:
  skills(on)


def defined(*names: str) -> Show:
  def ident(text: str) -> str:
    size = 0
    while size < len(text) and (text[size].isalnum() or text[size] == "_"):
      size += 1
    return text[:size]

  def named(line: str) -> str:
    for prefix in ("async def ", "def ", "class ", "type "):
      if line.startswith(prefix):
        return ident(line[len(prefix) :])
    name = ident(line)
    return name if line[len(name) :].lstrip()[:1] in (":", "=") else ""

  def show(lines: list[str]) -> list[int]:
    out: list[int] = []
    at, start, decorated = 0, 0, False
    while at < len(lines):
      first = at
      at += 1
      while at < len(lines) and (not lines[at] or lines[at][0] in " \t)]}"):
        at += 1
      if lines[first].startswith("@") or (decorated and lines[first].startswith("#")):
        decorated = True
        continue
      decorated = False
      end = at
      while end > first + 1 and not lines[end - 1]:
        end -= 1
      if named(lines[first]) in names:
        out.extend(range(start + 1, end + 1))
      start = at
    return out

  return show

compaction = """Compaction cuts this chain to the work that it still needs, and the chain goes on under its name.
- supersede(keep) cuts this chain to what the filter keep kept, and every act. compact() supersedes this chain with a
  filter that applies FILTERS in order, and its next word binds the summary
  that it is given and reads again each file whose read or write it kept, showing what changed. Its prompts, its
  rungs, the words that run and its module go on.
- A filter drops acts. latest() keeps the last read or write of each path, quiet() drops the commands, recent(n)
  keeps the acts of the last n replies, and await chosen() asks the model of this chain which acts to keep.
  together(*filters) applies filters in order.
- choice() asks on this chain the model that wrote its last reply, which reads the chain from its cache, which acts
  the work still needs, and what the rest holds, as ids and a summary. The turn of that answer stays in the chain.
- await condense() compacts this chain at once to what choice() chose, with the summary of the model, as compacted()
  does once.
- clear() cuts this chain to nothing, with no summary: its model reads from zero, and the chain keeps its name, its
  module, its prompts and its threads.
- compacted() wraps a chain: after an answer that reads more than SHARE of the window, it asks choice(), and at the
  next reply once that came, it compacts the chain to what the model chose. It moves, stops and pauses nothing.
- fitted() watches a chain: when its model refuses a reply because the prompt passes its window, it cuts the chain at
  once to its open prompts, so the next reply reads less and the chain goes on with no pause.
- The life word wraps each chain with compacted() and fitted(), so a chain compacts with a summary of the model
  before it passes its window, and the cut of fitted() is the last resort.
- A project changes the defaults in a skill of its own, whose word rebinds SHARE, FILTERS or BRIEF."""
SHARE = 0.6
OVERFLOWED = """The model refused the last reply of this chain, since its prompt passed the window of the model,
so compaction cut the chain to its open prompts: read again what the work still needs."""
BRIEF = """The chain grows past its window, and it goes on with what the work still needs.
Choose what it keeps: each act that holds a decision or a ruling of the operator, a brief, a finding that the work
still needs, and the last state of each command that matters. A step keeps all that it made, and an act keeps the
step that made it. The chain keeps its module, its prompts and its steps, so keep no act for a value that the module
holds. It reads again each file whose read or write you keep and shows what changed since, so keep the last read or
write of each file that the work still needs, and no other.
Close this prompt with one call, close((ids, summary)): the ids to keep, as list[str], as ["read3", "bash7"], and a
summary, in a few short lines, of what the acts that you drop hold and the work still needs to know. Do no other work
in this word."""


def together(*filters: Filter) -> Filter:
  def keep(acts: list) -> list:
    for one in filters:
      acts = one(acts)
    return acts

  return keep


def latest() -> Filter:
  def keep(acts: list) -> list:
    last = {t.path: a[1] for a in acts if a[0] in ("read", "write") and isinstance(t := peek(a[1]), Text)}
    return [
      a for a in acts if a[0] not in ("read", "write") or a[1] in last.values() or not isinstance(peek(a[1]), Text)
    ]

  return keep


def quiet() -> Filter:
  return lambda acts: [a for a in acts if a[0] != "bash"]


def recent(n: int) -> Filter:
  def keep(acts: list) -> list:
    rungs = [a[2] for a in acts if a[0] == "reply"][-n:] if n > 0 else []
    return [a for a in acts if any(under(a[1], one) for one in rungs)]

  return keep


def choice(on: str = "") -> Act:
  here = on or scope(acting())
  wrote = [str(a[4]) for a in transcript(here, "reply") if isinstance(peek(a[1]), tuple) and not operated(str(a[4]))]
  return prompt("tuple", BRIEF, to=wrote[-1] if wrote else module(here)["actor"], on=here)


async def chosen(on: str = "") -> Filter:
  got = await choice(on)
  assert isinstance(got, tuple)
  return take(*got[0])


FILTERS: list[Filter] = [latest(), recent(8)]


regrounded: set[str] = set()


def reground(on: str = "") -> None:
  here = on or scope(acting())
  voiced = {x[1] for x in reading(here) if x[0] == "tell"}
  held: dict[str, tuple[Text, bool]] = {}
  for a in reading(here):
    if (
      a[0] in ("read", "write")
      and a[1] in voiced
      and isinstance(t := peek(a[1]), Text)
      and "://" not in t.path
      and get(t.path.split("/")[0]) is None
    ):
      held[t.path] = (t, a[1] in regrounded)
  for path, (text, again) in held.items():
    seen = {x[1] for x in transcript(here) if x[0] == "read"}
    try:
      read(path, HEAD if again else differs(text.lines), on=on)
    except Refused:
      continue
    regrounded.update(x[1] for x in transcript(here) if x[0] == "read" and x[1] not in seen)


def headline(fact: tuple) -> str:
  """The first line of the first note of a tell, or else the kind of the fact."""
  match fact:
    case ("tell", _, _, [str(first), *_]):
      return first.split("\n")[0]
  return str(fact[0])


def supersede(keep: Filter | None = None, on: str = "") -> str:
  here = on or scope(acting())
  theirs = reading(here)
  kin = {here}
  acts = []
  for x in theirs:
    match x:
      case (str(kind), str(name), str(by), str(where), *words) if question(x):
        acts.append((kind, name, by, where, *words))
  for one in keep(acts) if keep else acts:
    name = one[1]
    while name not in kin and (b := get(name)):
      kin.add(name)
      name = b[2]

  heads = [headline(fact) for fact in theirs]
  lo = heads.index("chain()") if "chain()" in heads else len(theirs)
  hi = heads.index("#" + here, lo) if "#" + here in heads[lo:] else lo
  setup = {id(fact) for fact in theirs[lo:hi]}

  def stays(it: tuple) -> bool:
    if id(it) in setup:
      return True
    made = get(it[1])
    if made is None:
      return it[2] in kin
    return question(it) or ((made[2] if question(("reply", it[1])) else it[1]) in kin and it[0] != "carried")

  say("cut", here, [it for it in theirs if stays(it)])
  return here


def compact(filters: list[Filter] | None = None, summary: str = "", on: str = "") -> str:
  here = supersede(together(*(FILTERS if filters is None else filters)), on)
  name = "summary"
  while f"</s:{name}>" in summary:
    name += "_"
  quoted = f"<s:{name}>\n{summary}</s:{name}>\n" if summary else ""
  rung(f"{quoted}reground()", on=here)
  return here


def clear(on: str = "") -> str:
  return supersede(lambda _: [], on)


def compacted(on: str = "") -> Act:
  def ear(id):
    yield "started", id
    here, pending, seen, refused = scope(id), "", set(), False
    chose: tuple | None = None

    def keeping(ids: list[str], after: set) -> Filter:
      return lambda acts: take(*ids, *[a[1] for a in acts if a[1] not in after])(acts)

    while True:
      match (yield {id, here} | ({pending} if pending else set())):
        case ("done", about, _, Refused() as why) if about == pending:
          pending, refused = "", True
          yield told(id, "kept the chain as it is", why=why)
        case ("done", about, _, value) if about == pending:
          chose = (None, "")
          match value:
            case ([*listed], str() as summary):
              chose = ([keeping([i for i in listed if isinstance(i, str) and scope(i)], set(seen)), latest()], summary)
        case ("done", about, *_) if (
          question(("reply", about)) and scope(about) == here and not (pending or chose or refused)
        ):
          if (filled(about) or 0) > SHARE:
            seen = {fact[1] for fact in transcript(here) if question(fact)}
            pending = str(choice(on=here))
        case ("reply", about, *_) if chose and question(("reply", about)) and scope(about) == here:
          compact(chose[0], summary=chose[1].strip(), on=here)
          pending, chose = "", None

  return act("compacted", on, controlled(ear))


def fitted(on: str = "") -> Act:
  def ear(id):
    yield "started", id
    here, row = scope(id), False
    while True:
      match (yield {id, here}):
        case ("done", about, _, Refused() as why) if question(("reply", about)) and scope(about) == here:
          if isinstance(why, Overflow) and not row:
            compact([lambda acts: [a for a in acts if a[0] == "prompt" and not over(a[1])]], OVERFLOWED, here)
          row = isinstance(why, Overflow)
        case ("done", about, _, tuple()) if question(("reply", about)) and scope(about) == here:
          row = False

  return act("fitted", on, controlled(ear))


async def condense(on: str = "") -> str:
  here = on or scope(acting())
  before = {fact[1] for fact in transcript(here) if question(fact)}
  match await choice(here):
    case ([*listed], str() as summary):
      ids = [i for i in listed if isinstance(i, str) and scope(i)]

      def chose(acts: list) -> list:
        return take(*ids, *[a[1] for a in acts if a[1] not in before])(acts)

      return compact([chose, latest()], summary.strip(), here)
  return compact(on=here)

